with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co01ttd05f', 'practice', 'Écoute A2 : perturbations sur la ligne 4', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-ligne-4.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• en raison de (expression) : vì, do\n• le trafic (nom masculin) : sự lưu thông\n• interrompu (adjectif) : bị gián đoạn\n• la reprise (nom féminin) : sự hoạt động lại\n• la gêne (nom féminin) : sự phiền phức","explications":"• « En raison de » báo nguyên nhân: nghe kỹ ngay sau nó.\n• « Prévue vers » là giờ dự kiến, không phải giờ chắc chắn.\n• Thông báo có hai số tuyến (4 và 14): gắn mỗi số với vai trò của nó.","kyNang":"A2-CO-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-02T00:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk2000', 'a2co01ttd05f', 1, 'qcm', 'Pourquoi le trafic est-il interrompu ?', '{"options":["un incident technique","un accident de voyageur","une grève"]}'::jsonb, '{"answer":0}'::jsonb, '« en raison d''un incident technique ».'), ('qmvzhgtk2001', 'a2co01ttd05f', 2, 'qcm', 'Le problème concerne la ligne…', '{"options":["14","2","4"]}'::jsonb, '{"answer":2}'::jsonb, '« sur la ligne quatre ». La ligne 14 là đường đi thay.'), ('qmvzhgtk2002', 'a2co01ttd05f', 3, 'qcm', 'Le trafic doit reprendre vers…', '{"options":["17 h","7 h 30","17 h 30"]}'::jsonb, '{"answer":2}'::jsonb, '« La reprise du trafic est prévue vers dix-sept heures trente ».'), ('qmvzhgtk2003', 'a2co01ttd05f', 4, 'qcm', 'Que conseille-t-on aux voyageurs ?', '{"options":["prendre un taxi","prendre la ligne 14 ou un bus","attendre sur le quai"]}'::jsonb, '{"answer":1}'::jsonb, '« nous vous conseillons de prendre la ligne quatorze ou les bus de remplacement ».'), ('qmvzhgtk2004', 'a2co01ttd05f', 5, 'qcm', 'Les bus de remplacement sont…', '{"options":["devant la sortie 2","à la station Châtelet","devant la sortie 4"]}'::jsonb, '{"answer":0}'::jsonb, '« devant la sortie numéro deux ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
