with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co14vr605s', 'practice', 'Écoute A2 : un métier original', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-metier-original.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une abeille (nom féminin) : con ong\n• le miel (nom masculin) : mật ong\n• une ruche (nom féminin) : tổ ong\n• un comptable (nom masculin) : kế toán\n• s''ennuyer (verbe) : thấy chán","explications":"• So sánh « moins… que », « plus… que » thường mang đáp án.\n• Lý do hay nằm trong câu kể hoàn cảnh bằng imparfait (je passais, je m''ennuyais).","kyNang":"A2-CO-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-02T00:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk201x', 'a2co14vr605s', 1, 'qcm', 'Inès produit…', '{"options":["du miel","du vin","du fromage"]}'::jsonb, '{"answer":0}'::jsonb, '« je produis du miel ».'), ('qmvzhgtk201y', 'a2co14vr605s', 2, 'qcm', 'Elle a environ…', '{"options":["400 ruches","14 ruches","40 ruches"]}'::jsonb, '{"answer":2}'::jsonb, '« environ quarante ruches ».'), ('qmvzhgtk201z', 'a2co14vr605s', 3, 'qcm', 'Avant, elle travaillait…', '{"options":["dans une banque","dans une école","dans une ferme"]}'::jsonb, '{"answer":0}'::jsonb, '« j''étais comptable dans une banque ».'), ('qmvzhgtk2020', 'a2co14vr605s', 4, 'qcm', 'Elle a changé de métier parce qu''…', '{"options":["elle s''ennuyait","elle ne gagnait pas assez","elle a perdu son travail"]}'::jsonb, '{"answer":0}'::jsonb, '« je passais toute la journée devant un ordinateur, et je m''ennuyais ».'), ('qmvzhgtk2021', 'a2co14vr605s', 5, 'qcm', 'Aujourd''hui, par rapport à avant, elle gagne…', '{"options":["plus d''argent","moins d''argent","autant d''argent"]}'::jsonb, '{"answer":1}'::jsonb, '« Je gagne moins d''argent qu''avant, mais je suis plus libre ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co15w3q05t', 'practice', 'Écoute A2 : vivre à la campagne ou en ville', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-campagne-ville.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un auditeur (nom masculin) : thính giả\n• regretter (verbe) : hối tiếc\n• pur (adjectif) : trong lành\n• un loyer (nom masculin) : tiền thuê nhà\n• ça vaut la peine (expression) : đáng công, đáng tiền","explications":"• Hai người hai ý kiến: ghi tên mỗi người ở một cột.\n• « C''est vrai que…, mais… »: ý sau « mais » mới là ý kiến chính.","isPremium":true,"price":19000,"kyNang":"A2-CO-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-02T00:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk2022', 'a2co15w3q05t', 1, 'qcm', 'Claire habite à la campagne depuis…', '{"options":["6 mois","13 ans","3 ans"]}'::jsonb, '{"answer":2}'::jsonb, '« depuis trois ans ».'), ('qmvzhgtk2023', 'a2co15w3q05t', 2, 'qcm', 'Selon Claire, sa maison est…', '{"options":["plus petite que son ancien appartement","aussi grande que son ancien appartement","plus grande que son ancien appartement"]}'::jsonb, '{"answer":2}'::jsonb, '« deux fois plus grande que mon ancien appartement ».'), ('qmvzhgtk2024', 'a2co15w3q05t', 3, 'qcm', 'Pour Claire, le problème de la campagne, c''est…', '{"options":["le prix des maisons","le bruit","la voiture pour tout"]}'::jsonb, '{"answer":2}'::jsonb, '« Le problème, c''est la voiture : je l''utilise pour tout ».'), ('qmvzhgtk2025', 'a2co15w3q05t', 4, 'qcm', 'Karim aime la ville parce qu''…', '{"options":["il peut sortir et tout est près","il a une voiture","les loyers sont bas"]}'::jsonb, '{"answer":0}'::jsonb, '« J''aime sortir le soir », « Tout est près de chez moi ».'), ('qmvzhgtk2026', 'a2co15w3q05t', 5, 'qcm', 'Pour Karim, les loyers…', '{"options":["sont trop chers pour lui","sont chers, mais ça vaut la peine","ne sont pas chers"]}'::jsonb, '{"answer":1}'::jsonb, '« les loyers sont chers, mais pour moi, ça vaut la peine ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co16w8b05u', 'practice', 'Écoute A2 : mon voyage préféré', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-voyage-prefere.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• sans hésiter (expression) : không chút do dự\n• descendre (verbe) : đi xuống (phía nam)\n• accueillant (adjectif) : hiếu khách\n• par contre (expression) : ngược lại\n• la chaleur (nom féminin) : cái nóng","explications":"• « Ce qui vous a le plus plu » hỏi điều thích nhất; « par contre » mở ra điều không thích.\n• Nhiều tên thành phố trong bài: gắn mỗi tên với việc người nói làm ở đó.","isPremium":true,"price":19000,"kyNang":"A2-CO-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-02T00:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk2027', 'a2co16w8b05u', 1, 'qcm', 'Marc est allé au Vietnam…', '{"options":["l''année dernière","il y a deux ans","il y a dix ans"]}'::jsonb, '{"answer":1}'::jsonb, '« il y a deux ans ».'), ('qmvzhgtk2028', 'a2co16w8b05u', 2, 'qcm', 'Il est parti…', '{"options":["un mois avec sa femme","deux semaines tout seul","un mois avec des amis"]}'::jsonb, '{"answer":0}'::jsonb, '« Je suis parti un mois avec ma femme ».'), ('qmvzhgtk2029', 'a2co16w8b05u', 3, 'qcm', 'Pour descendre vers le sud, ils ont pris…', '{"options":["le bus","le train","l''avion"]}'::jsonb, '{"answer":1}'::jsonb, '« on est descendus vers le sud en train ».'), ('qmvzhgtk202a', 'a2co16w8b05u', 4, 'qcm', 'Qu''est-ce qui a été difficile pour lui ?', '{"options":["la chaleur","la nourriture","la langue"]}'::jsonb, '{"answer":0}'::jsonb, '« Par contre, la chaleur à Hô Chi Minh-Ville, c''était difficile ».'), ('qmvzhgtk202b', 'a2co16w8b05u', 5, 'qcm', 'L''année prochaine, il veut visiter…', '{"options":["Hô Chi Minh-Ville","Hanoï","Hué"]}'::jsonb, '{"answer":2}'::jsonb, '« je veux visiter le centre du pays, la ville de Hué ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co17wdq05v', 'practice', 'Écoute A2 : cuisiner à la maison', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-cuisiner-maison.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une obligation (nom féminin) : nghĩa vụ, việc bắt buộc\n• se détendre (verbe) : thư giãn\n• un plat (nom masculin) : món ăn\n• doué (adjectif) : có năng khiếu\n• commander (verbe) : gọi món, đặt hàng","explications":"• Ý kiến trái ngược thường mở bằng « Moi, je… ».\n• Mỗi thói quen đi với một thời điểm (le midi, le soir, le week-end): nghe kỹ thời điểm.","isPremium":true,"price":19000,"kyNang":"A2-CO-3","vong":"on","thuTu":5}'::jsonb, '2026-11-02T00:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk202c', 'a2co17wdq05v', 1, 'qcm', 'Pour Sophie, cuisiner, c''est…', '{"options":["une obligation","une perte de temps","un plaisir"]}'::jsonb, '{"answer":2}'::jsonb, '« c''est un plaisir, pas une obligation ».'), ('qmvzhgtk202d', 'a2co17wdq05v', 2, 'qcm', 'Le dimanche, Sophie…', '{"options":["prépare les repas de la semaine","ne cuisine pas","va au restaurant"]}'::jsonb, '{"answer":0}'::jsonb, '« le dimanche, je prépare des plats pour toute la semaine ».'), ('qmvzhgtk202e', 'a2co17wdq05v', 3, 'qcm', 'Selon Sophie, cuisiner à la maison est…', '{"options":["moins cher et meilleur pour la santé","plus cher mais meilleur","plus rapide que le restaurant"]}'::jsonb, '{"answer":0}'::jsonb, '« C''est moins cher que le restaurant et c''est meilleur pour la santé ».'), ('qmvzhgtk202f', 'a2co17wdq05v', 4, 'qcm', 'Lucas n''aime pas cuisiner parce qu''…', '{"options":["il n''a pas le temps et n''est pas doué","il n''aime pas manger","sa cuisine est trop petite"]}'::jsonb, '{"answer":0}'::jsonb, '« Je n''ai pas le temps et je ne suis pas doué ».'), ('qmvzhgtk202g', 'a2co17wdq05v', 5, 'qcm', 'Le week-end, Lucas…', '{"options":["mange bien grâce à sa copine","cuisine pour sa copine","commande une pizza"]}'::jsonb, '{"answer":0}'::jsonb, '« ma copine cuisine très bien, alors le week-end, je mange bien ». Pizza là buổi tối trong tuần.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co18wic05w', 'practice', 'Écoute A2 : l''émission du matin', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-emission-matin.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une émission (nom féminin) : chương trình (radio, TV)\n• un appel (nom masculin) : cuộc gọi\n• manquer à quelqu''un (verbe) : làm ai nhớ\n• se concentrer (verbe) : tập trung\n• efficace (adjectif) : hiệu quả","explications":"• Câu hỏi của người dẫn ở đầu chương trình cho biết chủ đề.\n• Ý kiến chung của mỗi người thường ở câu đầu (« Pour moi, c''est non ! »), lý do theo sau.\n• « Mes collègues me manquent »: chủ ngữ là thứ được nhớ, không phải người nhớ.","isPremium":true,"price":19000,"kyNang":"A2-CO-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-02T00:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk202h', 'a2co18wic05w', 1, 'qcm', 'Le thème de l''émission est…', '{"options":["le travail à la maison","la garde des enfants","les transports"]}'::jsonb, '{"answer":0}'::jsonb, '« travailler à la maison, c''est une bonne idée ? ».'), ('qmvzhgtk202i', 'a2co18wic05w', 2, 'qcm', 'Nathalie travaille chez elle…', '{"options":["3 jours par semaine","tous les jours","2 jours par semaine"]}'::jsonb, '{"answer":0}'::jsonb, '« trois jours par semaine depuis deux ans ».'), ('qmvzhgtk202j', 'a2co18wic05w', 3, 'qcm', 'Grâce au télétravail, Nathalie…', '{"options":["voit plus ses collègues","gagne plus d''argent","dort plus et est moins stressée"]}'::jsonb, '{"answer":2}'::jsonb, '« alors je dors plus et je suis moins stressée ».'), ('qmvzhgtk202k', 'a2co18wic05w', 4, 'qcm', 'Ce qui manque parfois à Nathalie, ce sont…', '{"options":["les transports","ses collègues","ses enfants"]}'::jsonb, '{"answer":1}'::jsonb, '« parfois, mes collègues me manquent ».'), ('qmvzhgtk202l', 'a2co18wic05w', 5, 'qcm', 'Bruno a arrêté le télétravail parce qu''…', '{"options":["il n''arrivait pas à se concentrer","il habite près du bureau","son chef a refusé"]}'::jsonb, '{"answer":0}'::jsonb, '« Je n''arrivais pas à me concentrer ».'), ('qmvzhgtk202m', 'a2co18wic05w', 6, 'qcm', 'Aujourd''hui, Bruno trouve qu''il est…', '{"options":["plus efficace à la maison","moins stressé chez lui","plus efficace au bureau"]}'::jsonb, '{"answer":2}'::jsonb, '« je vais au bureau tous les jours et je suis beaucoup plus efficace ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co19wnr05x', 'practice', 'Écoute A2 : conseiller ou se plaindre ?', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez les dialogues, puis associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-conseil-plainte.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• se plaindre (verbe) : phàn nàn\n• rembourser (verbe) : hoàn tiền\n• un ticket de caisse (nom masculin) : hoá đơn\n• conseiller (verbe) : khuyên\n• un roman policier (nom masculin) : tiểu thuyết trinh thám","explications":"• Ghép theo MỤC ĐÍCH câu nói, không theo nơi chốn.\n• « Tu devrais… » là cho lời khuyên, « Qu''est-ce que vous me conseillez ? » là xin lời khuyên.\n• Hai lời phàn nàn khác nhau ở đối tượng: món hàng hay cách phục vụ.","kyNang":"A2-CO-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-02T00:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk202x', 'a2co19wnr05x', 1, 'apparier', 'Associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.', '{"items":[{"id":"imvzhgtk202n","texte":"Dialogue 1"},{"id":"imvzhgtk202o","texte":"Dialogue 2"},{"id":"imvzhgtk202p","texte":"Dialogue 3"},{"id":"imvzhgtk202q","texte":"Dialogue 4"}],"choix":[{"id":"cmvzhgtk202r","texte":"Demander un conseil"},{"id":"cmvzhgtk202s","texte":"Se plaindre d''un service"},{"id":"cmvzhgtk202t","texte":"Donner un conseil"},{"id":"cmvzhgtk202u","texte":"Remercier quelqu''un"},{"id":"cmvzhgtk202v","texte":"Se plaindre d''un produit"},{"id":"cmvzhgtk202w","texte":"Demander un prix"}]}'::jsonb, '{"answers":{"imvzhgtk202n":"cmvzhgtk202v","imvzhgtk202o":"cmvzhgtk202t","imvzhgtk202p":"cmvzhgtk202r","imvzhgtk202q":"cmvzhgtk202s"}}'::jsonb, '1 : « il ne marche pas », « être remboursée » : phàn nàn về món hàng. 2 : « Tu devrais… » : cho lời khuyên. 3 : « Qu''est-ce que vous me conseillez ? » : xin lời khuyên. 4 : « ça fait quarante minutes qu''on attend » : phàn nàn về phục vụ.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co20wrt05y', 'practice', 'Écoute A2 : inviter ou refuser ?', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez les dialogues, puis associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-inviter-refuser.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une invitation (nom féminin) : lời mời\n• un mariage (nom masculin) : đám cưới\n• ça te dit de… ? (expression) : bạn có muốn… không?\n• faire un tour (expression) : đi dạo một vòng\n• annuler (verbe) : huỷ","explications":"• Nghe câu trả lời để phân biệt nhận lời, từ chối hay chưa quyết.\n• « C''est gentil, mais… » là cách từ chối lịch sự.\n• Huỷ hẹn khác từ chối: hẹn đã có từ trước.","isPremium":true,"price":19000,"kyNang":"A2-CO-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-02T00:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk2038', 'a2co20wrt05y', 1, 'apparier', 'Associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.', '{"items":[{"id":"imvzhgtk202y","texte":"Dialogue 1"},{"id":"imvzhgtk202z","texte":"Dialogue 2"},{"id":"imvzhgtk2030","texte":"Dialogue 3"},{"id":"imvzhgtk2031","texte":"Dialogue 4"}],"choix":[{"id":"cmvzhgtk2032","texte":"Proposer une sortie"},{"id":"cmvzhgtk2033","texte":"Accepter une invitation"},{"id":"cmvzhgtk2034","texte":"Féliciter quelqu''un"},{"id":"cmvzhgtk2035","texte":"Annuler un rendez-vous"},{"id":"cmvzhgtk2036","texte":"Refuser une invitation"},{"id":"cmvzhgtk2037","texte":"Demander un service"}]}'::jsonb, '{"answers":{"imvzhgtk202y":"cmvzhgtk2033","imvzhgtk202z":"cmvzhgtk2036","imvzhgtk2030":"cmvzhgtk2032","imvzhgtk2031":"cmvzhgtk2035"}}'::jsonb, '1 : « Bien sûr, nous serons là » : nhận lời mời. 2 : « C''est gentil, mais je ne peux pas » : từ chối lời mời. 3 : « ça te dit d''aller… ? » : rủ đi chơi, người kia chưa trả lời. 4 : « je ne peux pas venir à notre rendez-vous de demain » : huỷ hẹn.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co21wx105z', 'practice', 'Écoute A2 : excuses et rendez-vous', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez les dialogues, puis associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-excuses-rdv.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un dentiste (nom masculin) : nha sĩ\n• ça vous va ? (expression) : có tiện cho anh chị không?\n• une réunion (nom féminin) : cuộc họp\n• c''est noté (expression) : đã ghi lại\n• la monnaie (nom féminin) : tiền thối lại","explications":"• Có tình huống thừa rất gần nghĩa (đổi giờ hẹn và xác nhận hẹn): nghe xem giờ có đổi không.\n• Hai lời xin lỗi khác nhau ở lý do: đến muộn hay làm sai.","isPremium":true,"price":19000,"kyNang":"A2-CO-4","vong":"on","thuTu":4}'::jsonb, '2026-11-02T00:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk203j', 'a2co21wx105z', 1, 'apparier', 'Associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.', '{"items":[{"id":"imvzhgtk2039","texte":"Dialogue 1"},{"id":"imvzhgtk203a","texte":"Dialogue 2"},{"id":"imvzhgtk203b","texte":"Dialogue 3"},{"id":"imvzhgtk203c","texte":"Dialogue 4"}],"choix":[{"id":"cmvzhgtk203d","texte":"Prendre un rendez-vous"},{"id":"cmvzhgtk203e","texte":"S''excuser d''un retard"},{"id":"cmvzhgtk203f","texte":"Changer l''heure d''un rendez-vous"},{"id":"cmvzhgtk203g","texte":"S''excuser d''une erreur"},{"id":"cmvzhgtk203h","texte":"Confirmer un rendez-vous"},{"id":"cmvzhgtk203i","texte":"Demander son chemin"}]}'::jsonb, '{"answers":{"imvzhgtk2039":"cmvzhgtk203d","imvzhgtk203a":"cmvzhgtk203e","imvzhgtk203b":"cmvzhgtk203h","imvzhgtk203c":"cmvzhgtk203g"}}'::jsonb, '1 : « je voudrais un rendez-vous » : đặt hẹn mới. 2 : « Le bus n''est pas passé, j''ai dû venir à pied » : xin lỗi vì đến muộn. 3 : « c''est toujours à dix heures ? », « c''est noté » : xác nhận lại hẹn, giờ không đổi. 4 : « la mauvaise monnaie » : xin lỗi vì nhầm.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2co22zva060', 'practice', 'Écoute A2 : quatre dialogues, six situations', 'A2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez les dialogues, puis associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/a2-quatre-six.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• perdu (adjectif) : lạc đường\n• lourd (adjectif) : nặng\n• une permission (nom féminin) : sự cho phép\n• un renseignement (nom masculin) : thông tin\n• un stage (nom masculin) : kỳ thực tập","explications":"• Cùng là câu hỏi nhưng mục đích khác: « Je peux vous aider ? » là đề nghị giúp, « Est-ce que je peux… ? » là xin phép.\n• Giống đề thi: bốn hội thoại, sáu tình huống, hai tình huống thừa.","isPremium":true,"price":19000,"kyNang":"A2-CO-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-02T00:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzhgtk203u', 'a2co22zva060', 1, 'apparier', 'Associez chaque dialogue à ce que fait la personne. Il y a deux propositions en plus.', '{"items":[{"id":"imvzhgtk203k","texte":"Dialogue 1"},{"id":"imvzhgtk203l","texte":"Dialogue 2"},{"id":"imvzhgtk203m","texte":"Dialogue 3"},{"id":"imvzhgtk203n","texte":"Dialogue 4"}],"choix":[{"id":"cmvzhgtk203o","texte":"Demander un renseignement"},{"id":"cmvzhgtk203p","texte":"Faire une réclamation"},{"id":"cmvzhgtk203q","texte":"Proposer de l''aide"},{"id":"cmvzhgtk203r","texte":"Inviter quelqu''un"},{"id":"cmvzhgtk203s","texte":"Demander une permission"},{"id":"cmvzhgtk203t","texte":"Donner des nouvelles"}]}'::jsonb, '{"answers":{"imvzhgtk203k":"cmvzhgtk203q","imvzhgtk203l":"cmvzhgtk203s","imvzhgtk203m":"cmvzhgtk203o","imvzhgtk203n":"cmvzhgtk203t"}}'::jsonb, '1 : « Je peux vous aider à porter votre valise ? » : đề nghị giúp. 2 : « Est-ce que je peux partir une heure plus tôt ? » : xin phép. 3 : « à quelle heure ouvre la piscine ? » : hỏi thông tin. 4 : « Tout va bien ici, j''ai trouvé un appartement » : báo tin.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
