a à partir de…', '{"options":["100 m","1 000 m","2 000 m"]}'::jsonb, '{"answer":1}'::jsonb, '« à partir de mille mètres ».'), ('qmvzhgtk304z', 'a2co26gm6064', 5, 'qcm', 'Document 5 : Claire travaille…', '{"options":["dans une banque","dans une agence immobilière","dans un hôtel"]}'::jsonb, '{"answer":1}'::jsonb, '« de l''agence immobilière ».'), ('qmvzhgtk3050', 'a2co26gm6064', 6, 'qcm', 'Document 5 : le loyer est de…', '{"options":["570 € par mois","750 € par mois","750 € par semaine"]}'::jsonb, '{"answer":1}'::jsonb, '« sept cent cinquante euros par mois ».'), ('qmvzhgtk3051', 'a2co26gm6064', 7, 'qcm', 'Document 6 : pourquoi ce concert ?', '{"options":["pour son anniversaire","pour fêter ses 20 ans de carrière","pour aider une association"]}'::jsonb, '{"answer":1}'::jsonb, '« pour fêter ses vingt ans de carrière ».'), ('qmvzhgtk3052', 'a2co26gm6064', 8, 'qcm', 'Document 7 : combien de fois par jour faut-il prendre le médicament ?', '{"options":["2","1","3"]}'::jsonb, '{"answer":2}'::jsonb, '« Trois fois par jour ».'), ('qmvzhgtk3053', 'a2co26gm6064', 9, 'qcm', 'Document 7 : pendant combien de temps ?', '{"options":["un mois","une semaine","trois jours"]}'::jsonb, '{"answer":1}'::jsonb, '« et pendant une semaine ».'), ('qmvzhgtk3054', 'a2co26gm6064', 10, 'qcm', 'Document 8 : en cabine, on ne peut pas prendre…', '{"options":["de liquides de plus de 100 ml","d''ordinateur","de valise"]}'::jsonb, '{"answer":0}'::jsonb, '« les liquides de plus de cent millilitres sont interdits en cabine ».'), ('qmvzhgtk3055', 'a2co26gm6064', 11, 'qcm', 'Document 9 : ce qui plaît moins à cette personne, c''est…', '{"options":["le métro","les musées","le prix des cafés"]}'::jsonb, '{"answer":2}'::jsonb, '« Ce qui me plaît moins, c''est le prix des cafés ».'), ('qmvzhgtk3056', 'a2co26gm6064', 12, 'qcm', 'Document 10 : l''élève demande…', '{"options":["à changer de classe","à rendre son devoir plus tard","à partir plus tôt"]}'::jsonb, '{"answer":1}'::jsonb, '« je peux rendre mon devoir lu